/* The records benchmark input.
 *
 * Structs and unions -- nested, anonymous, in arrays, initialised at file
 * scope, reached through pointers and passed and returned by value -- with
 * enums as their tags and switch labels, typedefs for them and for scalars,
 * casts and sizeof: what acc gained after the other inputs were written.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

typedef struct {
    int count;
    unsigned char flags;
    long weight;
    char label[6];
} anchor_t;

anchor_t anchor_table[4] = {
    { 1, 2, 30000, "one" },
    { 2, 4, 40000, "two" },
    { 3 },
    { 4, 8 }
};

int weigh_anchor(anchor_t *entry, int scale) {
    int total = 0;

    for (int i = 0; i < sizeof anchor_table / sizeof anchor_table[0]; i++) {
        entry[i].count += scale;
        entry[i].flags |= 0;
        total += entry[i].count + entry[i].flags + (entry[i].weight > 35000);
        total += entry[i].label[0] == 't';
    }

    return total;
}

enum shape_buffer { CIRCLE_buffer, SQUARE_buffer, TRIANGLE_buffer = 5 };

struct figure_buffer {
    enum shape_buffer shape;
    union {
        int radius;
        struct { short width, height; } box;
        char sides[3];
    } size;
};

int area_buffer(struct figure_buffer *figure) {
    switch (figure->shape) {
    case CIRCLE_buffer:
        return 3 * figure->size.radius * figure->size.radius;
    case SQUARE_buffer:
        return figure->size.box.width * figure->size.box.height;
    case TRIANGLE_buffer:
        return figure->size.sides[0] + figure->size.sides[1] + figure->size.sides[2];
    }

    return 1;
}

int shapes_buffer(int n) {
    struct figure_buffer figures[3];

    figures[0].shape = CIRCLE_buffer;
    figures[0].size.radius = n;
    figures[1].shape = SQUARE_buffer;
    figures[1].size.box.width = n + 1;
    figures[1].size.box.height = 3;
    figures[2].shape = TRIANGLE_buffer;
    figures[2].size.sides[0] = 3;
    figures[2].size.sides[1] = 4;
    figures[2].size.sides[2] = n;

    return area_buffer(&figures[0]) + area_buffer(&figures[1])
           + area_buffer(figures + 2);
}

struct span_cursor { int start, end; char open; };

struct span_cursor widen_cursor(struct span_cursor span, int by) {
    span.start -= by;
    span.end += by;
    span.open = span.end - span.start > 7;

    return span;
}

int measure_cursor(struct span_cursor span) {
    return span.end - span.start + span.open;
}

int spans_cursor(int first) {
    struct span_cursor span = { first, first + 2 };
    struct span_cursor copy;

    span = widen_cursor(span, 2);
    copy = span;
    copy.end++;

    return measure_cursor(widen_cursor(copy, 1)) + measure_cursor(span);
}

struct link_header {
    int value;
    struct link_header *next;
    struct { int hits; char seen; } stats;
};

struct link_header chain_header[5];

int walk_header(int start) {
    struct link_header *at;
    int sum = 0;

    for (int i = 0; i < 5; i++) {
        chain_header[i].value = start + i;
        chain_header[i].next = i < 4 ? &chain_header[i + 1] : 0;
    }
    for (at = chain_header; at; at = at->next) {
        at->stats.hits++;
        at->stats.seen = 1;
        sum += at->value * at->stats.seen;
    }

    return sum + chain_header[0].next->next->value;
}

typedef unsigned char byte_margin;
typedef short half_margin;
typedef byte_margin *cursor_margin;

int pack_margin(int value) {
    byte_margin bytes[4];
    cursor_margin at = bytes;
    half_margin low = (half_margin) (value * 7);

    bytes[0] = (byte_margin) value;
    bytes[1] = (byte_margin) (value + 1);
    bytes[2] = (byte_margin) low;
    bytes[3] = (byte_margin) sizeof(byte_margin);

    return at[0] + at[1] + at[2] + at[3] + (int) (long) low;
}

